def transform(grid):
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])

    # Find background color (most common value)
    all_vals = [grid[r][c] for r in range(rows) for c in range(cols)]
    background = Counter(all_vals).most_common(1)[0][0]

    # Extract the 3x3 pattern from bottom-right of input
    pattern = [[background for _ in range(3)] for _ in range(3)]
    for rr in range(3):
        for cc in range(3):
            r = rows - 3 + rr
            c = cols - 3 + cc
            if 0 <= r < rows and 0 <= c < cols:
                pattern[rr][cc] = grid[r][c]

    # Generate 3x3 pattern array
    pattern_arr = [[0]*3 for _ in range(3)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                pr = r % 3
                pc = c % 3
                if pattern_arr[pr][pc] == 0:
                    pattern_arr[pr][pc] = grid[r][c]

    # Tile the pattern across output
    result = [[pattern_arr[r % 3][c % 3] for c in range(cols)] for r in range(rows)]

    return result
